(function(){
  window.TS=window.TS||{};
  const titles={dashboard:['YOUR PERSONAL WORKSPACE','Dashboard'],practice:['BUILD YOUR SKILL','Practice'],battle:['A FRIENDLY RACE','Typing Battle'],quests:['SMALL GOALS. REAL PROGRESS.','Daily Quests'],achievements:['CELEBRATE CONSISTENCY','Achievements'],statistics:['YOUR PROGRESS, MADE VISIBLE','Statistics'],settings:['MAKE IT YOURS','Settings']};
  const topics=['All topics','School','Daily Life','Technology','Nature','Science','Learning','Games'];
  function icon(name,size){return window.TS.UI.icon(name,size||18);}
  function statCard(label,value,unit,iconName,tone,note){return '<div class="card stat-card"><div class="stat-card-top"><span class="stat-label" style="margin:0">'+label+'</span><span class="stat-icon tone-'+tone+'">'+icon(iconName,19)+'</span></div><div><div class="stat-value">'+value+(unit?'<span class="stat-unit"> '+unit+'</span>':'')+'</div><div class="stat-delta">'+(note||'Based on your saved activity')+'</div></div></div>';}
  function sectionHead(title,desc,iconName,action){return '<div class="section-heading"><div><h2>'+icon(iconName||'activity',18)+title+'</h2>'+(desc?'<p>'+desc+'</p>':'')+'</div>'+(action||'')+'</div>';}
  function questCard(q,mini){const done=!!q.completed,bonus=!!q.bonusCompleted,pct=Math.min(100,(q.progress/Math.max(1,q.target))*100);if(mini)return '<div class="mini-quest '+(bonus?'mini-quest-bonus':'')+'"><div class="mini-quest-icon">'+icon(done?'check-circle':q.icon||'target',17)+'</div><div class="mini-quest-main"><div class="mini-quest-title">'+window.TS.UI.escape(q.title)+'</div><div class="mini-quest-meta">'+window.TS.UI.escape(q.description)+'</div>'+window.TS.UI.progress(q.progress,q.target)+'</div><div class="mini-quest-xp">'+(bonus?icon('sparkles',14)+' Bonus':done?icon('check-circle',14)+' Done':'+'+q.xp+' XP')+'</div></div>';
    return '<article class="card quest-card '+(done?'quest-completed ':'')+(bonus?'quest-bonus-completed':'')+'"><div class="quest-icon">'+icon(done?'check-circle':q.icon||'target',20)+'</div><div class="quest-body"><div class="quest-topline"><div><h3>'+window.TS.UI.escape(q.title)+'</h3><p>'+window.TS.UI.escape(q.description)+'</p></div><div class="quest-reward '+(bonus?'quest-reward-bonus':'')+'">'+(bonus?'Badge bonus':'+'+q.xp+' XP')+'</div></div><div class="quest-progressline"><span>'+ (done?'<span class="quest-status '+(bonus?'quest-status-bonus':'')+'">'+icon(bonus?'sparkles':'check',11)+' '+(bonus?'Bonus completed':'Completed')+'</span>':'Progress')+'</span><strong>'+window.TS.UI.number(Math.min(q.progress,q.target),q.type==='accuracy'?1:0)+' / '+window.TS.UI.number(q.target,q.type==='accuracy'?1:0)+(q.type==='minutes'?' sec':q.type==='accuracy'?'%':'')+'</strong></div>'+window.TS.UI.progress(q.progress,q.target)+'</div></article>';}
  function getActivity(){const state=window.TS.Storage.get();return state.sessions.map(x=>Object.assign({kind:'session'},x)).concat(state.battles.map(x=>Object.assign({kind:'battle'},x))).sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,5);}
  function activityRow(item){const batt=item.kind==='battle';const label=batt?'Typing Battle':item.type==='code'?'Code Typing':item.type==='paragraphs'?'Paragraphs':'Sentences';const iconName=batt?'swords':item.type==='code'?'code':item.type==='paragraphs'?'book-open':'keyboard';const right=batt?({win:'Victory',loss:'Defeat',draw:'Draw'}[item.outcome]||'Complete'):Math.round(item.wpm)+' WPM';const sub=batt?(item.difficulty+' · '+item.accuracy+'% accuracy'):window.TS.UI.formatDateTime(item.date)+' · '+item.accuracy+'% accuracy';return '<div class="activity-row"><div class="activity-type">'+icon(iconName,17)+'</div><div class="activity-main"><strong>'+label+'</strong><span>'+window.TS.UI.escape(sub)+'</span></div><div class="activity-numbers"><strong>'+right+'</strong><span>'+(batt?'match':Math.round(item.elapsedSeconds)+' sec')+'</span></div></div>';}
  function renderDashboard(){const s=window.TS.Storage.get(),sum=window.TS.Statistics.summary(),lvl=window.TS.Storage.getLevelInfo(s.profile.xp),quests=window.TS.DailyQuests.getToday(),showQuests=quests.filter(q=>!q.completed).slice(0,3).concat(quests.filter(q=>q.completed).slice(0,Math.max(0,3-quests.filter(q=>!q.completed).length))),month=window.TS.Storage.monthKey(),qcount=window.TS.Achievements.progress(month),monthlyBadge=window.TS.Achievements.getCurrent(month),activity=getActivity();const name=(s.playerName&&s.playerName!=='Player')?s.playerName:'there';
    return '<section class="welcome-card"><div class="welcome-copy"><div class="welcome-kicker">'+icon('sparkles',14)+' YOUR NEXT PERSONAL BEST STARTS HERE</div><h2>Ready to find your<br>typing rhythm, '+window.TS.UI.escape(name)+'?</h2><p>Build speed, improve accuracy, and turn a few focused minutes into a stronger daily habit.</p><div class="welcome-actions"><button class="btn btn-primary btn-lg" type="button" data-route="practice">'+icon('keyboard',17)+' Start practice</button><button class="btn btn-secondary btn-lg" type="button" data-route="battle">'+icon('swords',17)+' Quick battle</button></div></div><div class="welcome-art"><div class="welcome-art-card"><div class="welcome-art-icon">'+icon('zap',24)+'</div><div class="welcome-art-meta"><b>Build your streak</b><span>One session at a time</span><div class="art-mini-bars"><i></i><i></i><i></i><i></i><i></i></div></div></div></div></section>      <section class="stats-grid">'+statCard('BEST WPM',sum.bestWpm?Math.round(sum.bestWpm):'0','', 'gauge','blue',sum.totalSessions?'Personal record':'No sessions yet')+statCard('AVERAGE WPM',sum.averageWpm?Math.round(sum.averageWpm):'0','','activity','purple',sum.totalSessions?'Across '+sum.totalSessions+' sessions':'Starts after your first session')+statCard('AVG. ACCURACY',sum.totalSessions?sum.averageAccuracy.toFixed(1):'0','%','target','green',sum.totalSessions?'Across recorded sessions':'No accuracy data yet')+statCard('PRACTICE TIME',Math.floor(sum.totalSeconds/60),'min','clock','amber',sum.totalSeconds%60+' sec extra')+statCard('TOTAL SESSIONS',sum.totalSessions,'','keyboard','teal','Completed and recorded')+statCard('CURRENT STREAK',s.profile.currentStreak,'days','flame','rose',s.profile.longestStreak+' day longest streak')+'</section>      <div class="dashboard-grid"><div class="dashboard-column"><section class="card smart-card">'+sectionHead('Smart Practice','A fresh drill picked from your local library.','sparkles')+'<div class="smart-inner"><div class="smart-art">'+icon('brain',30)+'</div><div class="smart-copy"><h3>Practice with a purpose</h3><p>Choose a topic and let TypeStrike select a short, reviewed exercise matched to your current level.</p></div></div><div class="smart-footer"><div class="smart-level">'+icon('gauge',15)+' Suggested difficulty: <b>'+window.TS.Adaptive.label(window.TS.Adaptive.recommend(s.sessions,'sentences'))+'</b></div><button class="btn btn-primary btn-sm" data-action="smart-practice" type="button">Start smart practice '+icon('arrow-up-right',14)+'</button></div></section>      <section class="card card-pad">'+sectionHead('Recent activity','Your latest recorded sessions and battles.','activity','<button class="btn btn-ghost btn-sm" type="button" data-route="statistics">View history '+icon('chevron-right',14)+'</button>')+'<div class="activity-list">'+(activity.length?activity.map(activityRow).join(''):'<div class="empty-state"><div class="empty-icon">'+icon('chart',23)+'</div><h3>Your story starts here</h3><p>Complete a practice session or a battle and your real results will appear here.</p><button class="btn btn-secondary btn-sm" data-route="practice" type="button">Start first session</button></div>')+'</div></section></div>      <div class="dashboard-column"><section class="card card-pad">'+sectionHead('Daily quests','Small targets, useful rewards.','target','<button class="btn btn-ghost btn-sm" type="button" data-route="quests">View all '+icon('chevron-right',14)+'</button>')+'<div class="mini-quest-list">'+(showQuests.length?showQuests.map(q=>questCard(q,true)).join(''):'<div class="empty-state"><p>Today’s quests are complete. Great consistency!</p></div>')+'</div></section>      <section class="card card-pad monthly-preview-card">'+sectionHead('Monthly badge','One exclusive badge, refreshed every month.','medal','<button class="btn btn-ghost btn-sm" type="button" data-route="achievements">Badge library '+icon('chevron-right',14)+'</button>')+'<div class="month-progress"><div class="month-medal monthly-medal-tone">'+icon(monthlyBadge.icon,28)+'</div><div class="month-progress-body"><div class="monthly-preview-label">'+window.TS.UI.escape(monthlyBadge.monthLabel)+' · MONTHLY CHALLENGE</div><h3>'+window.TS.UI.escape(monthlyBadge.name)+'</h3><p>'+qcount+' of '+monthlyBadge.threshold+' daily quests completed</p>'+window.TS.UI.progress(qcount,monthlyBadge.threshold)+'<div class="month-footer"><span>'+window.TS.UI.escape(monthlyBadge.monthLabel)+'</span><span>'+(monthlyBadge.unlocked?'Added to your library':monthlyBadge.remaining+' quests to go')+'</span></div></div></div></section></div></div>';
  }
  function renderPractice(){
    const s=window.TS.Storage.get(),settings=s.settings;
    const type=settings.defaultContentType||'sentences',duration=settings.defaultDuration||'60';
    return `
      <div class="page-intro practice-page-intro">
        <div><span class="section-kicker">PRACTICE WORKSPACE</span><h2>Build speed, one focused session at a time.</h2><p>Choose what to type, set a challenge, then start. TypeStrike automatically clears away distractions once the session begins.</p></div>
        <div class="intro-actions"><button class="btn btn-secondary" type="button" data-action="practice-reset-setup">${icon('rotate-ccw',15)} Reset options</button></div>
      </div>
      <div class="practice-layout">
        <section class="card setup-card" aria-labelledby="practice-setup-heading">
          <div class="setup-title"><div class="setup-icon">${icon('sliders',20)}</div><div><h3 id="practice-setup-heading">Set up your practice</h3><p>Two quick choices before you begin</p></div><span class="setup-status-pill">READY TO START</span></div>
          <section class="setup-group" aria-labelledby="practice-content-heading">
            <div class="setup-group-heading"><span class="setup-step-number">01</span><div><h4 id="practice-content-heading">Choose your content</h4><p>Pick the kind of text you want to practise.</p></div></div>
            <div class="setup-fields content-fields">
              <div class="field"><label for="practice-content-type">Content type</label><select id="practice-content-type"><option value="sentences" ${type==='sentences'?'selected':''}>Random sentences</option><option value="paragraphs" ${type==='paragraphs'?'selected':''}>Paragraphs</option><option value="code" ${type==='code'?'selected':''}>Code typing</option></select></div>
              <div class="field" id="practice-topic-field" style="display:${type==='code'?'none':'flex'}"><label for="practice-topic">Topic</label><select id="practice-topic">${topics.map(t=>`<option value="${window.TS.UI.escape(t)}">${window.TS.UI.escape(t)}</option>`).join('')}</select></div>
              <div class="field" id="practice-language-field" style="display:${type==='code'?'flex':'none'}"><label for="practice-language">Programming language</label><select id="practice-language"><option>HTML</option><option>CSS</option><option>JavaScript</option><option>Python</option></select></div>
            </div>
          </section>
          <section class="setup-group" aria-labelledby="practice-challenge-heading">
            <div class="setup-group-heading"><span class="setup-step-number">02</span><div><h4 id="practice-challenge-heading">Set your challenge</h4><p>Difficulty, time limit and text length.</p></div></div>
            <div class="setup-fields challenge-fields">
              <div class="field"><label for="practice-difficulty">Difficulty</label><select id="practice-difficulty"><option value="adaptive" ${settings.adaptiveDifficulty?'selected':''}>Adaptive · recommended</option><option value="easy">Easy</option><option value="normal" ${!settings.adaptiveDifficulty?'selected':''}>Normal</option><option value="hard">Hard</option></select><small id="adaptive-helper">${settings.adaptiveDifficulty?'Recommended from your recent sessions.':'Choose a level to suit you.'}</small></div>
              <div class="field"><label for="practice-duration">Duration</label><select id="practice-duration"><option value="30" ${duration==='30'?'selected':''}>30 seconds</option><option value="60" ${duration==='60'?'selected':''}>60 seconds</option><option value="120" ${duration==='120'?'selected':''}>120 seconds</option><option value="unlimited" ${duration==='unlimited'?'selected':''}>Unlimited</option></select></div>
              <div class="field field-wide text-length-field"><label for="practice-length">Text length</label><div class="segmented" role="group" aria-label="Text length"><button type="button" data-length="short" class="active">Short</button><button type="button" data-length="medium">Medium</button><button type="button" data-length="long">Long</button></div><input type="hidden" id="practice-length" value="short"></div>
            </div>
          </section>
          <div class="focus-auto-note"><span class="focus-auto-icon">${icon('focus',18)}</span><div><strong>Focus Mode turns on automatically</strong><p>When Practice or Battle starts, TypeStrike switches to a clean full-screen typing view. Press <kbd>Esc</kbd> or use “Exit focus” to return to the full layout.</p></div><span class="focus-auto-state">AUTO</span></div>
          <div class="setup-bottom"><button class="btn btn-primary btn-lg start-session-button" type="button" data-action="start-practice">${icon('keyboard',17)} Start practice <span class="button-arrow">${icon('arrow-up-right',15)}</span></button><div class="setup-hint">${icon('shield',14)} No account needed. Your progress stays on this device when browser storage is available.</div></div>
        </section>
        <section class="card practice-preview" aria-labelledby="practice-preview-heading">
          <div class="preview-top"><div><span class="section-kicker">A QUICK LOOK</span><h3 id="practice-preview-heading">What your practice feels like</h3></div><span class="preview-tag">SAMPLE</span></div>
          <div class="preview-copy"><div class="preview-sample">A clear goal makes it easier to <strong>begin.</strong> Small steps can build a strong habit over time.</div></div>
          <div class="preview-checklist"><div>${icon('check-circle',15)} Clear character-by-character feedback</div><div>${icon('check-circle',15)} Live speed and accuracy stats</div><div>${icon('check-circle',15)} Real progress saved after a valid session</div></div>
        </section>
      </div>
      <div id="practice-session-root"></div>`;
  }
  function renderBattle(){const state=window.TS.Storage.get();return '<section class="battle-hero"><div class="battle-hero-copy"><div class="battle-kicker">'+icon('swords',15)+' TYPING BATTLE</div><h2>A little competition. A lot of progress.</h2><p>Race a local bot over the same passage. Both sides start together, and the winner is decided by who completes the text first. No online matchmaking or fake opponents.</p></div><div class="battle-mark">'+icon('swords',76)+'</div></section><div class="battle-setup-grid"><section class="card card-pad"><div class="section-heading"><div><h2>'+icon('target',18)+' Set up your match</h2><p>Choose the pace that feels right today.</p></div></div><div class="field"><label for="battle-name">Player name</label><input type="text" id="battle-name" maxlength="32" value="'+window.TS.UI.escape(state.playerName||'Player')+'" placeholder="Enter a display name"></div><div style="margin-top:17px" class="field-label">Choose difficulty</div><div class="difficulty-cards"><button type="button" class="difficulty-option" data-battle-difficulty="easy"><span class="diff-check">'+icon('check-circle',15)+'</span><span class="diff-icon">'+icon('shield',17)+'</span><strong>Easy</strong><small>Relaxed pace to warm up</small></button><button type="button" class="difficulty-option selected" data-battle-difficulty="normal"><span class="diff-check">'+icon('check-circle',15)+'</span><span class="diff-icon">'+icon('zap',17)+'</span><strong>Normal</strong><small>A balanced challenge</small></button><button type="button" class="difficulty-option" data-battle-difficulty="hard"><span class="diff-check">'+icon('check-circle',15)+'</span><span class="diff-icon">'+icon('flame',17)+'</span><strong>Hard</strong><small>A faster, accurate bot</small></button></div><button class="btn btn-primary btn-lg" type="button" data-action="start-battle" style="width:100%">'+icon('swords',17)+' Start battle</button></section><section class="card card-pad"><div class="section-heading"><div><h2>'+icon('shield',18)+' Fair-play rules</h2><p>Know how the race works.</p></div></div><div class="battle-rules"><div class="battle-rule"><div class="battle-rule-icon">'+icon('book-open',16)+'</div><div><strong>Same passage</strong><p>You and the bot get the exact same English text.</p></div></div><div class="battle-rule"><div class="battle-rule-icon">'+icon('clock',16)+'</div><div><strong>One shared start</strong><p>A short countdown begins the match for both sides.</p></div></div><div class="battle-rule"><div class="battle-rule-icon">'+icon('gauge',16)+'</div><div><strong>Different bot styles</strong><p>Difficulty changes the bot’s fixed pace and simulated accuracy.</p></div></div><div class="battle-rule"><div class="battle-rule-icon">'+icon('trophy',16)+'</div><div><strong>Earn rewards by playing</strong><p>Type at least 10 characters for a result to count toward rewards.</p></div></div></div></section></div><div id="battle-session-root" style="margin-top:18px"></div>';
  }
  function renderQuests(){const q=window.TS.DailyQuests.getToday(),complete=q.filter(x=>x.completed).length,reward=q.filter(x=>!x.completed).reduce((n,x)=>n+x.xp,0),earned=q.filter(x=>x.completed).reduce((n,x)=>n+x.xp,0),questMessage=complete===q.length?'All daily quests are complete. Come back tomorrow for a fresh set.':'Complete the goals below at your own pace.';return '<div class="page-intro"><div><h2>Turn practice into a daily habit.</h2><p>Quests progress only when a real practice session or battle meets the requirement. Rewards are applied once when each quest completes.</p></div><div>'+window.TS.UI.badge(window.TS.Storage.todayKey(),'blue')+'</div></div><div class="quest-summary-grid"><div class="card quest-summary"><div class="stat-icon tone-blue">'+icon('target',21)+'</div><div><strong>'+complete+' / '+q.length+'</strong><span>Quests completed today</span></div></div><div class="card quest-summary"><div class="stat-icon tone-green">'+icon('zap',21)+'</div><div><strong>+'+earned+' XP</strong><span>Quest XP earned today</span></div></div><div class="card quest-summary"><div class="stat-icon tone-purple">'+icon('trophy',21)+'</div><div><strong>+'+reward+' XP</strong><span>XP still available today</span></div></div></div><div class="section-heading"><div><h2>'+icon('calendar',18)+' Today’s quests</h2><p>'+complete===q.length?'All daily quests are complete. Come back tomorrow for a fresh set.':'Complete the goals below at your own pace.'+'</p></div><span class="badge badge-gray">Resets by device date</span></div><div class="quest-list">'+q.map(x=>questCard(x,false)).join('')+'</div><div class="card card-pad" style="margin-top:18px"><div class="section-heading"><div><h2>'+icon('shield',18)+' How rewards work</h2><p>Progress and reward history are stored locally.</p></div></div><p class="small" style="line-height:1.8;margin:0">Practice quests update after valid sessions. Battle quests update when a match is played actively. XP is awarded once per completed quest. Opening the website or generating a new exercise does not complete a quest or grant XP.</p></div>';
  }
  function renderAchievements(){
    const badge=window.TS.Achievements.getCurrent(),history=window.TS.Achievements.history(),count=window.TS.Achievements.progress(badge.month),daysInMonth=new Date(Number(badge.month.slice(0,4)),Number(badge.month.slice(5,7)),0).getDate(),daysLeft=Math.max(0,daysInMonth-new Date().getDate()+1),percent=Math.min(100,Math.round(count/badge.threshold*100)),remaining=Math.max(0,badge.threshold-count),bonusCount=window.TS.DailyQuests.countBonusCompletionsInMonth?window.TS.DailyQuests.countBonusCompletionsInMonth(badge.month):0;
    const rewardMin=badge.rewardXpMin||150,rewardMax=badge.rewardXpMax||250;
    const rewardValue=badge.unlocked?(badge.earnedRewardShort||('+'+(badge.reward||0)+' XP')):(rewardMin+'–'+rewardMax+' XP');
    const rewardExplain=badge.unlocked?(badge.earnedRewardText||'This reward is saved with your badge.'):'Or 10–25 real daily quests completed in advance for next month. The reward type is random.';
    const library=history.length?'<div class="badge-library-list">'+history.map(function(item){const questDetails=item.completedCount!=null?Math.min(Number(item.completedCount)||0,Number(item.threshold)||Number(item.completedCount)||0)+' monthly quests completed':'Earned achievement preserved from an earlier version';const rewardDetails=item.rewardSummary?' · '+item.rewardSummary:'';return '<article class="badge-library-item"><div class="badge-library-emblem '+window.TS.UI.escape(item.level||'blue')+'">'+icon(item.icon||'medal',27)+'</div><div class="badge-library-copy"><div class="badge-library-kicker">'+window.TS.UI.escape(item.monthLabel)+' <span>·</span> COLLECTED</div><h3>'+window.TS.UI.escape(item.name)+'</h3><p>'+window.TS.UI.escape(questDetails+rewardDetails)+'</p></div><div class="badge-library-date"><span>UNLOCKED</span><strong>'+window.TS.UI.escape(window.TS.UI.formatDate(item.unlockedAt))+'</strong><span class="badge badge-green">'+icon('check',11)+' Earned</span></div></article>';}).join('')+'</div>':'<div class="badge-library-empty"><div class="empty-icon">'+icon('medal',26)+'</div><h3>Your collection starts with one small win.</h3><p>Earn the current month’s badge to add it here. Unfinished badges expire at month-end and are not saved.</p><button class="btn btn-secondary" type="button" data-route="quests">Explore daily quests '+icon('arrow-right',15)+'</button></div>';
    return '<div class="page-intro badge-page-intro"><div><span class="section-kicker">MONTHLY COLLECTION</span><h2>One month. One unique badge.</h2><p>Every calendar month brings a different badge and its own quest target. Earn it before the month ends and it will join your library. Miss the target and that month’s badge is skipped—not saved.</p></div><div>'+window.TS.UI.badge(badge.monthLabel,'blue')+'</div></div>'+
      '<section class="monthly-challenge-card '+(badge.unlocked?'is-earned':'')+'"><div class="monthly-challenge-art '+window.TS.UI.escape(badge.level)+'"><div class="monthly-art-halo"></div><div class="monthly-art-ring"></div><div class="monthly-art-spark spark-one">✦</div><div class="monthly-art-spark spark-two">✦</div><div class="monthly-badge-glyph">'+icon(badge.icon,58)+'</div><span class="monthly-art-ribbon">'+(badge.unlocked?'COLLECTED':'LIMITED MONTH')+'</span></div><div class="monthly-challenge-content"><div class="monthly-challenge-topline"><span class="monthly-current-label">'+icon('calendar',14)+' '+window.TS.UI.escape(badge.monthLabel)+'</span><span class="badge '+(badge.unlocked?'badge-green':'badge-blue')+'">'+(badge.unlocked?'Badge earned':'Current challenge')+'</span></div><h2>'+window.TS.UI.escape(badge.name)+'</h2><p class="monthly-challenge-description">'+window.TS.UI.escape(badge.description)+'</p><div class="monthly-challenge-stats"><div><span>QUESTS COMPLETED</span><strong>'+count+' <small>/ '+badge.threshold+'</small></strong></div><div><span>BADGE REWARD</span><strong>'+window.TS.UI.escape(rewardValue)+'</strong></div><div><span>'+(badge.unlocked?'STATUS':'TIME LEFT')+'</span><strong>'+(badge.unlocked?'Secured':daysLeft+' <small>days</small>')+'</strong></div></div><div class="monthly-reward-note"><span class="monthly-reward-note-icon">'+icon(badge.unlocked?'gift':'sparkles',17)+'</span><div><strong>'+(badge.unlocked?'Reward received':'Generous badge reward')+'</strong><p>'+window.TS.UI.escape(rewardExplain)+'</p></div></div><div class="monthly-progress-caption"><span>Monthly quest progress</span><strong>'+percent+'%</strong></div><div class="monthly-progress-track" role="progressbar" aria-label="Monthly badge quest progress" aria-valuemin="0" aria-valuemax="'+badge.threshold+'" aria-valuenow="'+Math.min(count,badge.threshold)+'"><span style="width:'+percent+'%"></span></div>'+(bonusCount?'<div class="monthly-bonus-note">'+icon('sparkles',14)+' '+bonusCount+' quest completions were gifted by your previous month’s badge.</div>':'')+'<div class="monthly-challenge-foot"><span class="monthly-status-icon">'+icon(badge.unlocked?'check-circle':'target',17)+'</span><span>'+(badge.unlocked?'This badge is safely stored in your collection.':remaining+' more '+(remaining===1?'quest':'quests')+' needed before '+window.TS.UI.escape(badge.monthLabel)+' ends.')+'</span></div></div></section>'+
      '<section class="card card-pad badge-library-section"><div class="section-heading"><div><h2>'+icon('trophy',20)+' Your badge library</h2><p>Only badges you actually earned are kept here. Each entry remembers its month, year and reward.</p></div><span class="badge-library-count">'+history.length+' '+(history.length===1?'badge':'badges')+'</span></div>'+library+'</section>';
  }
  function renderStatistics(){const sm=window.TS.Statistics.summary(),s=window.TS.Storage.get(),history=window.TS.Statistics.history(),wpm=window.TS.Statistics.trend('wpm'),acc=window.TS.Statistics.trend('accuracy');const totalType=sm.totalSessions||1;const types=[['sentences','Sentences','keyboard',sm.byType.sentences],['paragraphs','Paragraphs','book-open',sm.byType.paragraphs],['code','Code typing','code',sm.byType.code]];return '<div class="page-intro"><div><h2>Every session tells a story.</h2><p>These charts are generated from your saved activity on this device. New users start with an empty history—no sample achievements or fabricated results.</p></div><button class="btn btn-secondary" type="button" data-action="export-data">'+icon('download',15)+' Export data</button></div><div class="statistics-kpis">'+statCard('TOTAL SESSIONS',sm.totalSessions,'','keyboard','blue','Valid recorded sessions')+statCard('PRACTICE TIME',Math.floor(sm.totalSeconds/60),'min','clock','purple',window.TS.UI.formatDuration(sm.totalSeconds)) +statCard('BEST WPM',sm.bestWpm?Math.round(sm.bestWpm):'0','','gauge','green','Personal best')+statCard('AVERAGE ACCURACY',sm.totalSessions?sm.averageAccuracy.toFixed(1):'0','%','target','amber','Across all sessions')+'</div><div class="statistics-grid"><section class="card chart-card"><div class="chart-title"><div><h3>WPM over time</h3><p>Latest '+wpm.length+' recorded sessions</p></div>'+window.TS.UI.badge('WPM','blue')+'</div><div class="chart-container">'+window.TS.Statistics.svgLine(wpm,{format:v=>Math.round(v)})+'</div></section><section class="card chart-card"><div class="chart-title"><div><h3>Accuracy over time</h3><p>Correct characters compared with typed characters</p></div>'+window.TS.UI.badge('Accuracy','green')+'</div><div class="chart-container">'+window.TS.Statistics.svgLine(acc,{format:v=>Math.round(v)+'%'})+'</div></section><section class="card chart-card"><div class="chart-title"><div><h3>Practice time by day</h3><p>Active typing time in the last 7 days</p></div>'+window.TS.UI.badge('Minutes','gray')+'</div><div class="chart-container">'+window.TS.Statistics.barMarkup(window.TS.Statistics.lastSevenDays())+'</div></section><section class="card chart-card"><div class="chart-title"><div><h3>Content mix</h3><p>Share of your recorded practice sessions</p></div>'+window.TS.UI.badge(sm.totalSessions+' total','gray')+'</div><div class="content-breakdown">'+types.map((t,i)=>'<div class="breakdown-row"><span class="breakdown-label">'+icon(t[2],15)+t[1]+'</span>'+window.TS.UI.progress(t[3],totalType)+'<strong>'+Math.round(t[3]/totalType*100)+'%</strong></div>').join('')+'<div class="divider"></div><div class="small muted">'+sm.wins+' battle wins · '+sm.losses+' losses · '+sm.draws+' draws · '+sm.completedQuests+' quests completed all-time</div></div></section></div><section class="card card-pad" style="margin-top:18px"><div class="section-heading"><div><h2>'+icon('activity',18)+' Recent session history</h2><p>Up to 20 latest saved practice sessions.</p></div><span class="badge badge-gray">'+sm.totalSessions+' sessions total</span></div>'+(history.length?'<div class="history-table-wrap"><table class="history-table"><thead><tr><th>DATE</th><th>CONTENT</th><th>DIFFICULTY</th><th>WPM</th><th>ACCURACY</th><th>TIME</th><th>XP</th></tr></thead><tbody>'+history.map(x=>'<tr><td>'+window.TS.UI.formatDateTime(x.date)+'</td><td><strong>'+(x.type==='code'?'Code typing':x.type==='paragraphs'?'Paragraphs':'Sentences')+'</strong></td><td>'+window.TS.UI.escape(window.TS.Adaptive.label(x.difficulty))+'</td><td>'+Math.round(x.wpm)+'</td><td>'+x.accuracy.toFixed(1)+'%</td><td>'+window.TS.UI.formatDuration(x.elapsedSeconds)+'</td><td>+'+x.xp+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty-state"><div class="empty-icon">'+icon('chart',23)+'</div><h3>No sessions to analyze yet</h3><p>Complete a valid practice run to populate your charts and session history with real data.</p><button class="btn btn-primary btn-sm" type="button" data-route="practice">Start practice</button></div>')+'</section><div class="statistics-kpis" style="margin-top:17px"><div class="card statistics-kpi"><div class="stat-label">CURRENT STREAK</div><div class="stat-value">'+sm.currentStreak+' <span class="stat-unit">days</span></div></div><div class="card statistics-kpi"><div class="stat-label">LONGEST STREAK</div><div class="stat-value">'+sm.longestStreak+' <span class="stat-unit">days</span></div></div><div class="card statistics-kpi"><div class="stat-label">BATTLE RECORD</div><div class="stat-value">'+sm.wins+'<span class="stat-unit">W</span> · '+sm.losses+'<span class="stat-unit">L</span></div></div><div class="card statistics-kpi"><div class="stat-label">QUESTS COMPLETED</div><div class="stat-value">'+sm.completedQuests+'</div></div></div>';
  }
  function settingRow(title,desc,key,checked){return '<div class="setting-row"><div><strong>'+title+'</strong><p>'+desc+'</p></div><label class="switch"><input type="checkbox" data-setting="'+key+'" '+(checked?'checked':'')+'><span class="switch-track"></span></label></div>';}
  function renderSettings(){const s=window.TS.Storage.get(),p=s.settings;return '<div class="page-intro"><div><h2>A workspace that works for you.</h2><p>Your preferences and progress stay in your browser. Use export/import to move your data between folders, browsers or devices.</p></div><span class="badge '+(window.TS.Storage.isPersistent()?'badge-green':'badge-amber')+'">'+icon(window.TS.Storage.isPersistent()?'shield':'alert-triangle',12)+' '+(window.TS.Storage.isPersistent()?'Local save available':'Temporary session storage')+'</span></div><div class="settings-grid"><div class="settings-column"><section class="card card-pad"><div class="section-heading"><div><h2>'+icon('keyboard',18)+' Practice preferences</h2><p>Set your default way to train.</p></div></div>'+'<div class="setting-row"><div><strong>Automatic Focus Mode</strong><p>Practice and Battle always open in a distraction-free typing view. Press Esc to leave it.</p></div><span class="badge badge-blue">Always on</span></div>'+settingRow('Adaptive difficulty','Recommend difficulty using your recent sessions.','adaptiveDifficulty',p.adaptiveDifficulty)+'<div class="setting-row"><div><strong>Default content</strong><p>Preselected when Practice opens.</p></div><select class="setting-select" data-setting-select="defaultContentType"><option value="sentences" '+(p.defaultContentType==='sentences'?'selected':'')+'>Sentences</option><option value="paragraphs" '+(p.defaultContentType==='paragraphs'?'selected':'')+'>Paragraphs</option><option value="code" '+(p.defaultContentType==='code'?'selected':'')+'>Code typing</option></select></div><div class="setting-row"><div><strong>Default duration</strong><p>Starting timer for a new practice test.</p></div><select class="setting-select" data-setting-select="defaultDuration"><option value="30" '+(p.defaultDuration==='30'?'selected':'')+'>30 sec</option><option value="60" '+(p.defaultDuration==='60'?'selected':'')+'>60 sec</option><option value="120" '+(p.defaultDuration==='120'?'selected':'')+'>120 sec</option><option value="unlimited" '+(p.defaultDuration==='unlimited'?'selected':'')+'>Unlimited</option></select></div></section>      <section class="card card-pad"><div class="section-heading"><div><h2>'+icon('volume-2',18)+' Sound feedback</h2><p>Short local tones, generated by your browser.</p></div></div>'+settingRow('Typing sounds','A quiet tone for each key, with a different error tone.','sound',p.sound)+'<div class="range-setting"><div><strong>Volume</strong><span id="volume-label">'+p.volume+'%</span></div><input type="range" min="0" max="100" step="5" value="'+p.volume+'" data-setting-range="volume" aria-label="Sound effects volume"></div></section>      <section class="card card-pad background-music-card"><div class="section-heading"><div><h2>'+icon('music',18)+' Background music</h2><p>Starts enabled at a gentle 15% volume and loops while you use TypeStrike.</p></div><span class="badge badge-blue">Local file</span></div>'+settingRow('Enable background music','Loop your chosen soundtrack while you practice, battle or browse.','backgroundMusic',p.backgroundMusic)+'<div class="range-setting"><div><strong>Music volume</strong><span id="background-music-volume-label">'+p.backgroundMusicVolume+'%</span></div><input type="range" min="0" max="100" step="5" value="'+p.backgroundMusicVolume+'" data-setting-range="backgroundMusicVolume" aria-label="Background music volume"></div></section>      <section class="card card-pad"><div class="section-heading"><div><h2>'+icon('sun',18)+' Appearance & accessibility</h2><p>Adjust the typing area and motion preferences.</p></div></div><div class="range-setting"><div><strong>Typing text size</strong><span id="font-size-label">'+p.fontSize+' px</span></div><input type="range" min="16" max="32" step="1" value="'+p.fontSize+'" data-setting-range="fontSize" aria-label="Typing text size"></div>'+settingRow('Reduce motion','Limit transitions and cursor animation.','reducedMotion',p.reducedMotion)+'</section></div>      <div class="settings-column"><section class="card card-pad"><div class="section-heading"><div><h2>'+icon('user',18)+' Player profile</h2><p>Used as your display name in local battles.</p></div></div><div class="field"><label for="profile-name">Display name</label><input id="profile-name" type="text" maxlength="32" value="'+window.TS.UI.escape(s.playerName||'Player')+'" placeholder="Player"></div><button type="button" class="btn btn-primary" data-action="save-profile-name" style="margin-top:12px">Save display name</button></section>      <section class="card card-pad"><div class="section-heading"><div><h2>'+icon('database',18)+' Data management</h2><p>Back up or restore your progress.</p></div></div><div class="data-action-row"><div class="data-action-icon">'+icon('download',18)+'</div><div class="data-action-copy"><strong>Export data</strong><p>Download XP, settings, quests, badges and session history as a TypeStrike backup (.tstrike).</p></div><button class="btn btn-secondary btn-sm" type="button" data-action="export-data">Export</button></div><div class="data-action-row"><div class="data-action-icon">'+icon('upload',18)+'</div><div class="data-action-copy"><strong>Import data</strong><p>Restore a valid .tstrike backup. Older .json backups are also accepted. Import replaces current local progress.</p></div><button class="btn btn-secondary btn-sm" type="button" data-action="import-data">Import</button></div><div class="data-action-row danger-row"><div class="data-action-icon">'+icon('trash',18)+'</div><div class="data-action-copy"><strong>Reset progress</strong><p>Permanently clear local sessions, XP, quests, badges and preferences.</p></div><button class="btn btn-danger btn-sm" type="button" data-action="reset-data">Reset</button></div><div class="settings-footnote">'+icon('circle-help',14)+' Browser storage can be isolated for different file paths. Export a backup before moving or deleting the project folder.</div></section><section class="card card-pad"><div class="section-heading"><div><h2>'+icon('shield',18)+' Privacy & offline use</h2><p>No account, server or cloud sync.</p></div></div><div class="privacy-list"><div><span class="privacy-check">'+icon('check',13)+'</span><span>Practice content and bot logic run locally.</span></div><div><span class="privacy-check">'+icon('check',13)+'</span><span>Charts contain only saved local activity.</span></div><div><span class="privacy-check">'+icon('check',13)+'</span><span>No external fonts, APIs or runtime CDNs.</span></div></div></section></div></div>';
  }
  function render(){document.body.classList.remove('session-result-practice','session-result-battle');const route=window.TS.Router.current||'dashboard',pair=titles[route]||titles.dashboard;const ey=document.getElementById('page-eyebrow'),head=document.getElementById('page-heading'),date=document.getElementById('today-label'),main=document.getElementById('main-content');if(ey)ey.textContent=pair[0];if(head)head.textContent=pair[1];if(date)date.textContent=window.TS.UI.todayLabel();if(!main)return;const renderers={dashboard:renderDashboard,practice:renderPractice,battle:renderBattle,quests:renderQuests,achievements:renderAchievements,statistics:renderStatistics,settings:renderSettings};main.innerHTML=(renderers[route]||renderDashboard)();window.TS.Icons.replace(document);window.TS.Navigation.setActive(route);window.TS.Settings.apply();}
  function currentPracticeConfig(){const get=id=>document.getElementById(id);let type=get('practice-content-type')?.value||window.TS.Storage.get().settings.defaultContentType,language=get('practice-language')?.value||'JavaScript',topic=type==='code'?'Code':get('practice-topic')?.value||'All topics',rawDiff=get('practice-difficulty')?.value||'adaptive',difficulty=rawDiff==='adaptive'?window.TS.Adaptive.recommend(window.TS.Storage.get().sessions,type):rawDiff,duration=get('practice-duration')?.value||window.TS.Storage.get().settings.defaultDuration,length=get('practice-length')?.value||'short',focus=true;return {contentType:type,type:type,language:language,topic:topic,difficulty:difficulty,requestedDifficulty:rawDiff,duration:duration,durationSeconds:duration==='unlimited'?null:Number(duration),length:length,focusMode:focus};}
  function startPractice(config,textOverride){config=config||currentPracticeConfig();config.focusMode=true;const item=textOverride?{text:textOverride,topic:config.topic,language:config.language}:window.TS.ContentGenerator.generate(config);const s=window.TS.Storage.get();s.settings.defaultContentType=config.contentType;s.settings.defaultDuration=config.duration;s.settings.focusMode=config.focusMode;window.TS.Storage.save();const root=document.getElementById('practice-session-root');if(root)root.innerHTML='';window.TS.TypingEngine.start({text:item.text,rootId:'practice-session-root',mode:'practice',config:config,meta:{topic:config.topic,language:config.language}});if(config.requestedDifficulty==='adaptive'&&!window.TS.FocusMode.active())window.TS.UI.toast('Adaptive difficulty', 'This exercise is set to '+window.TS.Adaptive.label(config.difficulty)+' based on your recent results.','info');}
  function showPracticeResult(result){const root=document.getElementById('practice-session-root');if(!root)return;document.body.classList.add('session-result-practice');const m=result.metrics,s=result.session,newBest=!!(s&&window.TS.Storage.get().sessions.every(x=>x.id===s.id||x.wpm<=s.wpm));root.innerHTML='<section class="card result-card"><div class="result-hero"><div class="result-medal">'+icon(result.valid?'trophy':'clock',28)+'</div><div><span class="badge '+(result.valid?'badge-green':'badge-gray')+'">'+(result.valid?'SESSION RECORDED':'SESSION NOT RECORDED')+'</span><h2 style="margin-top:7px">'+(result.reason==='complete'?'Excellent work.':'Time is up.')+'</h2><p>'+(result.valid?'Your session and rewards have been saved locally.':'Type at least 10 characters, or finish the full text, to record a timed session and earn XP.')+'</p>'+(newBest&&s?'<div style="margin-top:9px">'+window.TS.UI.badge('New personal WPM best','green')+'</div>':'')+'</div></div><div class="result-stats"><div class="result-stat"><span>Words per minute</span><strong>'+Math.round(m.wpm)+'</strong></div><div class="result-stat"><span>Accuracy</span><strong>'+m.accuracy.toFixed(1)+'%</strong></div><div class="result-stat"><span>Errors</span><strong>'+m.errors+'</strong></div><div class="result-stat"><span>Correct characters</span><strong>'+m.correctCharacters+'</strong></div><div class="result-stat"><span>Time taken</span><strong>'+window.TS.UI.formatDuration(m.elapsedSeconds)+'</strong></div><div class="result-stat"><span>Text progress</span><strong>'+Math.round(m.progress)+'%</strong></div></div><div class="result-hero" style="padding:0 0 20px;border:0;gap:12px"><div class="stat-icon tone-blue">'+icon('zap',21)+'</div><div><strong style="display:block;font-size:15px">+'+result.earnedXp+' XP earned</strong><span class="muted small">'+(result.valid?'Includes rewards for this valid session. Quest rewards are added separately when goals are met.':'No XP was added for this incomplete run.')+'</span></div></div><div class="result-actions"><button class="btn btn-primary" type="button" data-action="practice-retry">'+icon('rotate-ccw',15)+' Try again</button><button class="btn btn-secondary" type="button" data-action="generate-new-result">'+icon('refresh',15)+' Generate new text</button><button class="btn btn-ghost" type="button" data-route="dashboard">'+icon('home',15)+' Dashboard</button></div></section>';window.TS.UI.toast(result.valid?'Practice saved':'Practice not recorded',result.valid?'+'+result.earnedXp+' XP · stats and quests updated.':'No reward was issued for this run.','info');}
  function generateNewFromCurrent(){const c=window.TS.TypingEngine.getCurrent();if(!c)return startPractice();const run=()=>{const opts=c.options||{},cfg=opts.config||{contentType:c.type,difficulty:c.difficulty,durationSeconds:c.durationSeconds,focusMode:c.focus,topic:c.meta.topic,language:c.meta.language};const next=window.TS.ContentGenerator.generate(cfg);const updated=Object.assign({},opts,{text:next.text,meta:{topic:cfg.topic||next.topic,language:cfg.language||next.language},config:cfg,rootId:'practice-session-root'});startPractice(cfg,next.text);};if(window.TS.TypingEngine.isDirty())window.TS.UI.confirm({title:'Replace this exercise?',message:'Your current typing run has not finished. Replacing it will discard this run, without changing saved results.',confirmText:'Generate new text',cancelText:'Keep typing',danger:true}).then(ok=>{if(ok)run();});else run();}
  function retryPractice(){const c=window.TS.TypingEngine.getCurrent();if(!c){startPractice();return;}const opts=c.options||{};window.TS.TypingEngine.start(Object.assign({},opts,{rootId:'practice-session-root'}));}
  function exportData(){try{const payload='TSTRIKE-BACKUP/1\n'+JSON.stringify(window.TS.Storage.get()),blob=new Blob([payload],{type:'application/vnd.typestrike.backup'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='typestrike-backup-'+window.TS.Storage.todayKey()+'.tstrike';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);window.TS.UI.toast('Backup ready','Your .tstrike backup file is ready to keep or transfer.','success');}catch(e){window.TS.UI.toast('Export failed','Your browser could not create the backup file.','error');}}
  async function importData(){const input=document.getElementById('import-file-input');if(input){input.value='';input.click();}}
  function readBackupFile(file){if(file.size>5*1024*1024)return Promise.reject(new Error('Backup files must be smaller than 5 MB.'));return file.text().then(text=>{const header='TSTRIKE-BACKUP/1\n';if(text.startsWith(header))return JSON.parse(text.slice(header.length));if(file.name.toLowerCase().endsWith('.json'))return JSON.parse(text);throw new Error('This is not a valid .tstrike backup. Export a new backup from TypeStrike Settings.');});}
  async function resetData(){const ok=await window.TS.UI.confirm({title:'Reset all progress?',message:'This permanently removes saved sessions, XP, streaks, quest history, badges and settings from this browser. Export a backup first if you may need it.',confirmText:'Reset everything',cancelText:'Cancel',danger:true,icon:'trash'});if(!ok)return;window.TS.Storage.reset();window.TS.DailyQuests.ensureToday();window.TS.Router.force(window.TS.Router.current);window.TS.UI.toast('Progress reset','A fresh TypeStrike profile is ready.','info');}
  async function clickAction(action,button){switch(action){case 'start-practice':startPractice();break;case 'smart-practice':window.TS.Router.navigate('practice').then(ok=>{if(ok){const e=document.getElementById('practice-difficulty');if(e)e.value='adaptive';startPractice(currentPracticeConfig());}});break;case 'practice-reset-setup':window.TS.Storage.get().settings.defaultDuration='60';window.TS.Storage.get().settings.defaultContentType='sentences';window.TS.Storage.get().settings.focusMode=true;window.TS.Storage.save();render();window.TS.UI.toast('Options reset','Practice setup returned to its defaults.','info');break;case 'pause-test':window.TS.TypingEngine.togglePause();break;case 'restart-test':{const c=window.TS.TypingEngine.getCurrent();if(c&&c.typed.length){const ok=await window.TS.UI.confirm({title:'Restart this run?',message:'Your current progress will be discarded. Completed sessions will remain saved.',confirmText:'Restart',danger:true});if(ok)window.TS.TypingEngine.restart();}else window.TS.TypingEngine.restart();break;}case 'new-text':generateNewFromCurrent();break;case 'exit-focus':window.TS.FocusMode.disable();break;case 'practice-retry':retryPractice();break;case 'generate-new-result':generateNewFromCurrent();break;case 'start-battle':{const diff=document.querySelector('[data-battle-difficulty].selected')?.dataset.battleDifficulty||'normal';const name=document.getElementById('battle-name')?.value||'Player';window.TS.Battle.start({difficulty:diff,playerName:name});break;}case 'battle-rematch':{const b=window.TS.Battle.getState();if(b){const options={difficulty:b.difficulty,playerName:b.player};window.TS.Battle.reset();window.TS.Battle.start(options);}break;}case 'battle-change':window.TS.Battle.reset();render();window.TS.Navigation.setActive('battle');break;case 'export-data':exportData();break;case 'import-data':importData();break;case 'reset-data':await resetData();break;case 'save-profile-name':{const val=(document.getElementById('profile-name')?.value||'Player').trim().slice(0,32)||'Player';window.TS.Storage.get().playerName=val;window.TS.Storage.save();window.TS.UI.toast('Profile saved','Battle display name updated.','success');render();break;}}
  }
  function onChange(e){const t=e.target;if(t.id==='practice-content-type'){const code=t.value==='code',lang=document.getElementById('practice-language-field'),topic=document.getElementById('practice-topic-field');if(lang)lang.style.display=code?'flex':'none';if(topic)topic.style.display=code?'none':'flex';const hint=document.getElementById('adaptive-helper');if(hint)hint.textContent=t.value==='code'?'Adaptive difficulty uses your recent code sessions.':'Recommended from your recent sessions.';}
    if(t.matches('[data-setting]')){const key=t.dataset.setting;window.TS.Settings.update(key,t.checked);if(key==='sound')window.TS.UI.toast(t.checked?'Sound enabled':'Sound muted',t.checked?'Typing tones are enabled.':'Typing tones are disabled.','info');else if(key==='backgroundMusic'){if(t.checked){window.TS.BackgroundMusic.playFromUserGesture().then(function(playing){if(playing)window.TS.UI.toast('Background music enabled','Now playing music/background-music.mp3.','success');});}else{window.TS.BackgroundMusic.pause();window.TS.UI.toast('Background music paused','Background music is off.','info');}}else window.TS.UI.toast('Setting updated','Your preference has been saved.','info');}
    if(t.matches('[data-setting-select]')){window.TS.Settings.update(t.dataset.settingSelect,t.value);window.TS.UI.toast('Preference saved','New practice sessions will use this default.','info');}
    if(t.matches('[data-setting-range]')){const key=t.dataset.settingRange,val=Number(t.value),label=document.getElementById(key==='volume'?'volume-label':key==='backgroundMusicVolume'?'background-music-volume-label':'font-size-label');if(label)label.textContent=val+(key==='fontSize'?' px':'%');if(key==='fontSize')document.documentElement.style.setProperty('--practice-font-size',val+'px');if(key==='backgroundMusicVolume')window.TS.BackgroundMusic.setVolume(val);if(e.type==='change')window.TS.Settings.update(key,val);}
    
    if(t.id==='practice-difficulty'){const h=document.getElementById('adaptive-helper');if(h)h.textContent=t.value==='adaptive'?'Recommended from your recent sessions.':'Manual difficulty selected.';}
  }
  function init(){window.TS.Storage.load();if(window.TS.BackgroundMusic)window.TS.BackgroundMusic.init();window.TS.DailyQuests.ensureToday();window.TS.Achievements.check(window.TS.Storage.monthKey());window.TS.UI.init();window.TS.Settings.apply();window.TS.Router.init();window.TS.Navigation.init();const main=document.getElementById('main-content');if(main){main.addEventListener('click',async e=>{const action=e.target.closest('[data-action]');if(action){await clickAction(action.dataset.action,action);return;}const len=e.target.closest('[data-length]');if(len){document.querySelectorAll('[data-length]').forEach(b=>b.classList.toggle('active',b===len));const val=document.getElementById('practice-length');if(val)val.value=len.dataset.length;return;}const diff=e.target.closest('[data-battle-difficulty]');if(diff){document.querySelectorAll('[data-battle-difficulty]').forEach(b=>b.classList.toggle('selected',b===diff));return;}});main.addEventListener('change',onChange);main.addEventListener('input',e=>{if(e.target.matches('[data-setting-range]'))onChange(e);});}
    const importInput=document.getElementById('import-file-input');if(importInput)importInput.addEventListener('change',async e=>{const file=e.target.files&&e.target.files[0];if(!file)return;try{const data=await readBackupFile(file);const ok=await window.TS.UI.confirm({title:'Import this backup?',message:'Importing will replace all current TypeStrike data with the selected backup. Export your current progress first if you need a copy.',confirmText:'Import backup',danger:true});if(!ok)return;window.TS.Storage.importObject(data);window.TS.DailyQuests.ensureToday();window.TS.Achievements.check(window.TS.Storage.monthKey());render();window.TS.UI.toast('Import complete','Backup data was validated and loaded.','success');}catch(err){window.TS.UI.toast('Import failed',err.message||'The selected file is not a valid TypeStrike backup.','error');}finally{importInput.value='';}});
    render();if(!window.TS.Storage.isPersistent())window.TS.UI.toast('Temporary storage only','This browser is not allowing localStorage for this file path. Progress may be lost when you close the tab.','error');window.addEventListener('beforeunload',()=>{if(window.TS.TypingEngine)window.TS.TypingEngine.abandon();});}
  window.TS.App={init:init,render:render,showPracticeResult:showPracticeResult,startPractice:startPractice,exportData:exportData};
  document.addEventListener('DOMContentLoaded',init);
})();
